// Factory for the architectures whose loader, tensor creation and graph builder exist ONLY as src/models classes.
//
// The legacy path (llm_load_hparams / create_tensors_helper::create_tensors / llm_build_context::llama_build_graph) has no case for these names, so a GGUF of any of
// them ended at "unknown architecture" (MEASURED 2026-10-04, test-llama-archs matrix 22: 47 of 163). Every other architecture keeps the plain llama_model and the
// legacy path, so nothing that loads today changes. GENERATED by temp/_tca_gen_factory_1004.py from the matrix's failing list, LLM_ARCH_NAMES and models/models.h.

#include "llama-model.h"
#include "models/models.h"

llama_model * llama_model_create_for_arch(llm_arch arch, const llama_model_params & params) {
    // the class base builds its LLM_TN in its constructor, before the loader has set model.arch; hand it the architecture here
    llama_model_pending_arch() = arch;
    llama_model * model = nullptr;
    switch (arch) {
        case LLM_ARCH_PHIMOE: model = new llama_model_phimoe(params); break;
        case LLM_ARCH_PLAMO2: model = new llama_model_plamo2(params); break;
        case LLM_ARCH_PLAMO3: model = new llama_model_plamo3(params); break;
        case LLM_ARCH_MINICPM3: model = new llama_model_minicpm3(params); break;
        case LLM_ARCH_GEMMA3N: model = new llama_model_gemma3n(params); break;
        case LLM_ARCH_MAMBA2: model = new llama_model_mamba2(params); break;
        case LLM_ARCH_JAMBA: model = new llama_model_jamba(params); break;
        case LLM_ARCH_FALCON_H1: model = new llama_model_falcon_h1(params); break;
        case LLM_ARCH_COHERE2MOE: model = new llama_model_cohere2moe(params); break;
        case LLM_ARCH_OLMO2: model = new llama_model_olmo2(params); break;
        case LLM_ARCH_OLMOE: model = new llama_model_olmoe(params); break;
        case LLM_ARCH_DEEPSEEK: model = new llama_model_deepseek(params); break;
        case LLM_ARCH_DEEPSEEK32: model = new llama_model_deepseek32(params); break;
        case LLM_ARCH_JAIS2: model = new llama_model_jais2(params); break;
        case LLM_ARCH_NEMOTRON: model = new llama_model_nemotron(params); break;
        case LLM_ARCH_NEMOTRON_H: model = new llama_model_nemotron_h(params); break;
        case LLM_ARCH_NEMOTRON_H_MOE: model = new llama_model_nemotron_h_moe(params); break;
        case LLM_ARCH_EXAONE: model = new llama_model_exaone(params); break;
        case LLM_ARCH_EXAONE4: model = new llama_model_exaone4(params); break;
        case LLM_ARCH_EXAONE_MOE: model = new llama_model_exaone_moe(params); break;
        case LLM_ARCH_GRANITE_SWA: model = new llama_model_granite_swa(params); break;
        case LLM_ARCH_BAILINGMOE: model = new llama_model_bailingmoe(params); break;
        case LLM_ARCH_DOTS3NOTE: model = new llama_model_dots3note(params); break;
        case LLM_ARCH_ARCEE: model = new llama_model_arcee(params); break;
        case LLM_ARCH_AFMOE: model = new llama_model_afmoe(params); break;
        case LLM_ARCH_HUNYUAN_DENSE: model = new llama_model_hunyuan_dense(params); break;
        case LLM_ARCH_HUNYUAN_VL: model = new llama_model_hunyuan_vl(params); break;
        case LLM_ARCH_HY_V3: model = new llama_model_hy_v3(params); break;
        case LLM_ARCH_HY_V4: model = new llama_model_hy_v4(params); break;
        case LLM_ARCH_SPARK2_5: model = new llama_model_spark2_5(params); break;
        case LLM_ARCH_DREAM: model = new llama_model_dream(params); break;
        case LLM_ARCH_SMALLTHINKER: model = new llama_model_smallthinker(params); break;
        case LLM_ARCH_LLADA: model = new llama_model_llada(params); break;
        case LLM_ARCH_LLADA_MOE: model = new llama_model_llada_moe(params); break;
        case LLM_ARCH_GROVEMOE: model = new llama_model_grovemoe(params); break;
        case LLM_ARCH_APERTUS: model = new llama_model_apertus(params); break;
        case LLM_ARCH_MINIMAX_01: model = new llama_model_minimax_01(params); break;
        case LLM_ARCH_COGVLM: model = new llama_model_cogvlm(params); break;
        case LLM_ARCH_RND1: model = new llama_model_rnd1(params); break;
        case LLM_ARCH_PANGU_EMBED: model = new llama_model_pangu_embed(params); break;
        case LLM_ARCH_PADDLEOCR: model = new llama_model_paddleocr(params); break;
        case LLM_ARCH_MAINCODER: model = new llama_model_maincoder(params); break;
        case LLM_ARCH_KIMI_LINEAR: model = new llama_model_kimi_linear(params); break;
        case LLM_ARCH_TALKIE: model = new llama_model_talkie(params); break;
        case LLM_ARCH_NANBEIGE: model = new llama_model_nanbeige(params); break;
        case LLM_ARCH_QWEN3TTS: model = new llama_model_qwen3tts(params); break;
        case LLM_ARCH_POCKETTTS: model = new llama_model_pockettts(params); break;
        // recurrent-op architectures (GGML_OP_RWKV_WKV6 / GGML_OP_GATED_LINEAR_ATTN / GGML_OP_RWKV_WKV7): the legacy path has no builder for them
        case LLM_ARCH_RWKV6: model = new llama_model_rwkv6(params); break;
        case LLM_ARCH_RWKV6QWEN2: model = new llama_model_rwkv6qwen2(params); break;
        case LLM_ARCH_RWKV7: model = new llama_model_rwkv7(params); break;
        case LLM_ARCH_ARWKV7: model = new llama_model_arwkv7(params); break;
        // upstream-new classes of the 2026-11-05 merge with no legacy create_tensors case (they loaded as "unknown architecture")
        case LLM_ARCH_BEAM: model = new llama_model_beam(params); break;
        case LLM_ARCH_CLEF: model = new llama_model_clef(params); break;
        case LLM_ARCH_FLINT: model = new llama_model_flint(params); break;
        case LLM_ARCH_GEMMA_EMBEDDING2: model = new llama_model_gemma_embedding2(params); break;
        case LLM_ARCH_GLM5_NEXT: model = new llama_model_glm5_next(params); break;
        case LLM_ARCH_HRM_TEXT: model = new llama_model_hrm_text(params); break;
        case LLM_ARCH_KOLIBRI1: model = new llama_model_kolibri1(params); break;
        case LLM_ARCH_MMFREELM: model = new llama_model_mmfreelm(params); break;
        case LLM_ARCH_MAION_CODER: model = new llama_model_maion_coder(params); break;
        case LLM_ARCH_MAPLE: model = new llama_model_maple(params); break;
        case LLM_ARCH_MUSE_SPARK: model = new llama_model_muse_spark(params); break;
        case LLM_ARCH_SENSENOVA_U1: model = new llama_model_sensenova_u1(params); break;
        case LLM_ARCH_VLLM_DECISION2: model = new llama_model_vllm_decision2(params); break;
        // "modern-bert" (upstream spelling, e.g. ggml-org/Julia-1-GGUF decision model): the exact-name scan in llm_arch_from_string
        // returns LLM_ARCH_MODERN_BERT before the "modern-bert" -> LLM_ARCH_MODERNBERT alias is consulted, and only our
        // "modernbert" enum has a legacy create_tensors case, so these files died as "unknown architecture" (MEASURED 2026-11-06,
        // canonical 6865e9115). Our own "modernbert" GGUFs keep the legacy path.
        case LLM_ARCH_MODERN_BERT: model = new llama_model_modern_bert(params); break;
        // Same defect class, found by cortex/scripts/check_arch_load_path.py (2026-11-06): each of these names is in LLM_ARCH_NAMES,
        // has a compiled src/models class, and had neither a legacy create_tensors case nor a dispatch here -> "unknown architecture".
        case LLM_ARCH_CHAMELEON: model = new llama_model_chameleon(params); break;
        case LLM_ARCH_DEEPSEEK2OCR: model = new llama_model_deepseek2ocr(params); break;
        case LLM_ARCH_EUROBERT: model = new llama_model_eurobert(params); break;
        case LLM_ARCH_GRANITE_SWITCH: model = new llama_model_granite_switch(params); break;
        case LLM_ARCH_JINA_BERT_V3: model = new llama_model_jina_bert_v3(params); break;
        case LLM_ARCH_LLAMA_EMBED: model = new llama_model_llama_embed(params); break;
        case LLM_ARCH_NEO_BERT: model = new llama_model_neo_bert(params); break;
        case LLM_ARCH_NOMIC_BERT_MOE: model = new llama_model_nomic_bert_moe(params); break;
        case LLM_ARCH_PLM: model = new llama_model_plm(params); break;
        case LLM_ARCH_WAVTOKENIZER_DEC: model = new llama_model_wavtokenizer_dec(params); break;
        // GPT-J: the arch name was accepted but no loader or graph existed anywhere (upstream has the name only); src/models/gptj.cpp is new
        case LLM_ARCH_GPTJ: model = new llama_model_gptj(params); break;
        default: break;
    }
    llama_model_pending_arch() = LLM_ARCH_UNKNOWN;
    return model;
}

// LLM_ARCH_DFLASH has a legacy loader (z-lab DFlash, DSpark, DSV4 drafts: src/llama-hparams.cpp, create_dflash_tensors,
// build_dflash), so the arch alone does not pick the class. A GGUF carrying lilicorr.* keys is a LiLiCorr draft, which only
// upstream's class models (src/models/dflash.cpp, llama_model_dflash; upstream 977c48a25) can load and run; the caller peeks
// the key and asks for the class here. Row S69-FORK-DFLASH-ENGINE-LACKS-LILICORR-MROPE-DSPARK-NEMOTRON-UPSTREAM-MODEL-UNREACHED-2026-11-05-01.
llama_model * llama_model_create_dflash_class(const llama_model_params & params) {
    llama_model_pending_arch() = LLM_ARCH_DFLASH;
    llama_model * model = new llama_model_dflash(params);
    llama_model_pending_arch() = LLM_ARCH_UNKNOWN;
    return model;
}

